/bin/bash -lc "python - <<'PY'
import numpy as np, mujoco
from sim import Sim, MIN_PELVIS_Z, MIN_TORSO_UP

names=Sim().actuator_names(); idx={n:i for i,n in enumerate(names)}

kp=np.array([200,200,260,320,80, 200,200,260,320,80, 160, 60,60,30,30, 60,60,30,30],float)
kd=kp*0.4

def trial(dhp,dknee,dank,steps=650):
    sim=Sim(); m=sim.model; d=sim.data
    act_dof=np.array([int(m.jnt_dofadr[m.actuator_trnid[i,0]]) for i in range(m.nu)],dtype=int)
    q0=d.qpos[7:26].copy(); qdes=q0.copy()
    for side in ['left','right']:
        qdes[idx[f'{side}_hip_pitch']] += dhp
        qdes[idx[f'{side}_knee']] += dknee
        qdes[idx[f'{side}_ankle']] += dank
    ok=0
    for i in range(steps):
        q=d.qpos[7:26]; qd=d.qvel[6:25]
        tau=d.qfrc_bias[act_dof] + kp*(qdes-q) - kd*qd
        tau=np.clip(tau,m.actuator_ctrlrange[:,0],m.actuator_ctrlrange[:,1])
        d.ctrl[:] = tau
        mujoco.mj_step(m,d)
        if (i+1)%10==0:
            p=sim.pelvis_position(); up=sim.torso_up()
            if p[2]>=MIN_PELVIS_Z and up>=MIN_TORSO_UP:
                ok += 1
        if sim.pelvis_position()[2] < 0.6:
            return None
    pel=sim.pelvis_position(); up=sim.torso_up();
    return pel,up,ok/(steps/10)

best=None
for dhp in [-0.45,-0.4,-0.35,-0.3,-0.25,-0.2]:
  for dknee in [-0.1,0.0,0.1,0.2,0.3]:
    for dank in [-0.2,-0.1,0.0,0.1,0.2]:
      out=trial(dhp,dknee,dank)
      if out is None:
        continue
      pel,up,frac=out
      if frac < 0.95:
        continue
      score=pel[0]
      if best is None or score>best[0]:
        best=(score,dhp,dknee,dank,pel,up,frac)

print('best',best)
PY"

